contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_unused >= 0);
        require(address(this).balance >= 0);

        uint beforeCBal = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCBal = address(c).balance;

        assert(
            (reverted && afterCBal == beforeCBal) ||
            (!reverted && afterCBal == 0)
        );
    }

    receive() external payable {}
}

