// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 _unused) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_unused >= 0);
        vm.assume(address(this).balance >= 0);
        uint beforeCBal = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterCBal = address(c).balance;
        assertTrue((reverted && afterCBal == beforeCBal) ||
            (!reverted && afterCBal == 0));
    }

    function testFuzz_run(uint256 _unused) public {
        _run(_unused);
    }

    receive() external payable {}
}
